/* ------------------------------ Synchronizacja z Supabase ------------------------------ */
// Pola zaczynające się od "_" to metadane lokalne (_synced, _cloudAt) – nigdy nie trafiają do chmury.
const toCloud = (p) => Object.fromEntries(Object.entries(p).filter(([k]) => !k.startsWith('_')));

const commentKey = (c) => `${c.author}|${c.ts || 0}|${c.text}`;

// Scala dwie wersje tego samego zawodnika: pola profilu z nowszej (updatedAt),
// zdjęcia / reakcje / komentarze są łączone, żeby nikt nikomu nie nadpisał lajków.
// PIN profilu: tylko lekki zamek przed przypadkową zmianą cudzych danych (hash trzymany razem z profilem)
const pinHashOf = (id, pin) => {
  const str = `ia1|${id}|${pin}`;
  let h1 = 0xdeadbeef;
  let h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i += 1) {
    const c = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 2654435761);
    h2 = Math.imul(h2 ^ c, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0');
};

const mergePlayers = (a, b) => {
  const aNewer = (a.updatedAt || 0) >= (b.updatedAt || 0);
  const base = aNewer ? a : b;
  const other = aNewer ? b : a;
  const deleted = Array.from(new Set([...(a.deletedPhotos || []), ...(b.deletedPhotos || [])]));
  const map = new Map();
  [...(base.photos || []), ...(other.photos || [])].forEach((ph) => {
    if (deleted.includes(ph.id)) return;
    const ex = map.get(ph.id);
    if (!ex) {
      map.set(ph.id, ph);
      return;
    }
    const reactions = {};
    new Set([...Object.keys(ex.reactions || {}), ...Object.keys(ph.reactions || {})]).forEach((k) => {
      reactions[k] = Math.max(ex.reactions?.[k] || 0, ph.reactions?.[k] || 0);
    });
    const cm = new Map();
    [...(ex.comments || []), ...(ph.comments || [])].forEach((c) => {
      const k = commentKey(c);
      if (!cm.has(k)) cm.set(k, c);
    });
    map.set(ph.id, { ...ex, reactions, comments: Array.from(cm.values()).sort((x, y) => (x.ts || 0) - (y.ts || 0)) });
  });
  const photos = Array.from(map.values()).sort((x, y) => (y.ts || 0) - (x.ts || 0));
  // dzienniki (ważenia, serie / rekordy) tylko się powiększają – łączymy je, żeby nic nie zginęło
  const unionBy = (xs, ys, keyFn) => {
    const m = new Map();
    [...(xs || []), ...(ys || [])].forEach((it) => { const k = keyFn(it); if (!m.has(k)) m.set(k, it); });
    return Array.from(m.values()).sort((x, y) => (x.ts || 0) - (y.ts || 0));
  };
  // jedno ważenie na dzień – wygrywa najpóźniejsze (także po scaleniu z innym urządzeniem)
  const perDay = new Map();
  unionBy(a.weighIns, b.weighIns, (w) => w.ts).forEach((w) => perDay.set(dayKey(w.ts), w));
  const weighIns = Array.from(perDay.values());
  const prMap = new Map();
  [...(a.prs || []), ...(b.prs || [])].forEach((r) => {
    const ex = prMap.get(r.id);
    if (!ex) { prMap.set(r.id, r); return; }
    const vm = new Map();
    [...(ex.votes || []), ...(r.votes || [])].forEach((v) => { const cur = vm.get(v.by); if (!cur || (v.ts || 0) > (cur.ts || 0)) vm.set(v.by, v); });
    prMap.set(r.id, { ...ex, votes: Array.from(vm.values()) });
  });
  const prs = Array.from(prMap.values()).sort((x, y) => (x.ts || 0) - (y.ts || 0));
  const dm = new Map();
  [...(a.duels || []), ...(b.duels || [])].forEach((d) => {
    const ex = dm.get(d.id);
    dm.set(d.id, ex ? { ...ex, cancelled: Boolean(ex.cancelled || d.cancelled) } : d);
  });
  const duels = Array.from(dm.values());
  // dziennik jedzenia: suma wpisów z obu urządzeń bez usuniętych, tylko ostatnie ${MEAL_KEEP_DAYS} dni
  const deletedMeals = Array.from(new Set([...(a.deletedMeals || []), ...(b.deletedMeals || [])])).slice(-300);
  const mealsCut = Date.now() - MEAL_KEEP_DAYS * DAY_MS;
  const meals = unionBy(a.meals, b.meals, (m) => m.id).filter((m) => !deletedMeals.includes(m.id) && m.ts >= mealsCut);
  const deletedSets = Array.from(new Set([...(a.deletedSets || []), ...(b.deletedSets || [])])).slice(-100);
  const mealSets = unionBy(a.mealSets, b.mealSets, (x) => x.id).filter((x) => !deletedSets.includes(x.id)).slice(-30);
  return { ...base, photos, weighIns, prs, duels, meals, deletedMeals, mealSets, deletedSets, deletedPhotos: deleted, updatedAt: Math.max(a.updatedAt || 0, b.updatedAt || 0) };
};

async function sbRequest(cfg, path, { method = 'GET', body, prefer } = {}) {
  const res = await fetch(`${cfg.url}/rest/v1/${path}`, {
    method,
    headers: { apikey: cfg.key, Authorization: `Bearer ${cfg.key}`, 'Content-Type': 'application/json', ...(prefer ? { Prefer: prefer } : {}) },
    body: body === undefined ? undefined : JSON.stringify(body)
  });
  if (!res.ok) {
    let detail = '';
    try {
      const j = await res.json();
      detail = [j.code, j.message || j.error, j.hint].filter(Boolean).join(' – ');
    } catch (_) {}
    const err = new Error(detail || `HTTP ${res.status}`);
    err.status = res.status;
    throw err;
  }
  if (res.status === 204) return null;
  const text = await res.text();
  return text ? JSON.parse(text) : null;
}

const explainSbError = (e) => {
  const s = e?.status;
  const m = String(e?.message || '');
  if (!s && /fetch|network|load failed/i.test(m)) return 'Brak połączenia z Supabase – sprawdź internet oraz adres Project URL.';
  if (s === 404 || /PGRST205|PGRST106|does not exist|schema cache/i.test(m)) return 'W Supabase nie ma tabeli „squad_players”. Wklej i uruchom skrypt SQL (przycisk „Kopiuj SQL” poniżej) – wystarczy raz.';
  if (s === 401 || s === 403 || /row-level security|42501|permission denied|JWT|api key/i.test(m)) return 'Supabase odrzuca zapis (brak uprawnień RLS lub zły klucz). Uruchom skrypt SQL z tego okna – dodaje wymagane uprawnienia.';
  return `Błąd Supabase${s ? ` (${s})` : ''}: ${m}`;
};

